"""Exact save reports are formatted by the app, not regenerated by an LLM."""
from __future__ import annotations

import math
import re
import unicodedata


def _plain(text):
    return "".join(char for char in unicodedata.normalize("NFKD", text.casefold())
                   if not unicodedata.combining(char))


def is_report_request(text):
    """Recognize explicit saved-data questions, not general game advice."""
    text = _plain(text)
    save_reference = bool(re.search(r"\b(save|snapshot|salvamento|salvo|salvos)\b", text))
    ownership = bool(re.search(r"\b(my|mine|meu|minha|tenho|i have)\b", text))
    game_reference = bool(re.search(r"\b(my game|meu jogo)\b", text))
    field = bool(re.search(r"\b(units|unidades|nanites|quicksilver|balances?|saldos?|play[ -]?time|hours? (?:played|on this save)|horas? (?:jogadas|neste save)|tempo de jogo)\b", text))
    count_field = bool(re.search(r"\b(base|bases|inventory|inventario)\b", text) and
                       re.search(r"\b(count|total|many|much|numero|quantos|quantas|quantidade)\b", text))
    if not field and not count_field and re.search(r"\b(import|upload|format|parser|decoder|configure|importar|formato|configurar|funciona|vincular)\b", text):
        return False
    overview = bool(re.search(r"\b(overview|summary|summarize|summarise|info|information|stats|statistics|resumo|resuma|dados|informacoes|estatisticas)\b", text))
    recall = bool(re.search(r"\b(know|remember|lembra|sabe|conhece)\b", text))
    asks = bool(re.search(r"\b(list|show|tell|what|how many|how much|quanto|quantos|quantas|qual|quais|liste|mostre|informe|diga)\b", text))
    advice = bool(re.search(r"\b(earn|farm|increase|get|spend|buy|use|invest|upgrade|ganhar|farmar|conseguir|aumentar|gastar|comprar|usar|investir|melhorar)\b", text))
    explicit_report = bool(re.search(
        r"\b(list|show|report|liste|mostre|informe)\s+(?:(?:me|my|current|saved|the|meus?|minhas?|os|as|atuais)\s+)*"
        r"(units|unidades|nanites|quicksilver|balances?|saldos?|stats|statistics|dados|estatisticas|base count|inventory count|play[ -]?time|hours? (?:played|on this save)|horas? (?:jogadas|neste save)|tempo de jogo)\b", text))
    if advice and not explicit_report:
        return False
    if explicit_report and (save_reference or game_reference or ownership):
        return True
    if (save_reference or game_reference) and (overview or recall or (asks and (field or count_field))):
        return True
    return bool(asks and ownership and (field or count_field) and not advice)


def report_locale(text, ui_locale="en"):
    words = _plain(text)
    if re.search(r"\b(meu|minha|quanto|quantos|quantas|qual|quais|liste|mostre|informe|diga|dados|salvamento|resuma|lembra|tenho)\b", words):
        return "pt"
    if re.search(r"\b(my|what|show|list|tell|using|how|saved|know|remember)\b", words):
        return "en"
    return "pt" if ui_locale == "pt" else "en"


def _number(value, locale):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return "Desconhecido" if locale == "pt" else "Unknown"
    if isinstance(value, float) and not value.is_integer():
        result = f"{value:,}"
        return result.replace(",", "_").replace(".", ",").replace("_", ".") if locale == "pt" else result
    result = f"{int(value):,}"
    return result.replace(",", ".") if locale == "pt" else result


def _count(payload, key):
    values = payload.get(key)
    return len(values) if isinstance(values, list) else None


def _play_time(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or value < 0 or (isinstance(value, float) and not math.isfinite(value)):
        return None
    total = int(value)
    days, total = divmod(total, 86400)
    hours, total = divmod(total, 3600)
    minutes, seconds = divmod(total, 60)
    clock = f"{hours:02d}:{minutes:02d}:{seconds:02d}"
    return f"{days}d {clock}" if days else clock


def verified_save(snapshot):
    """Machine-read reference data, kept separate from generated prose."""
    if not snapshot:
        return None
    import math
    payload = snapshot.get("payload") or {}
    def value(key):
        number = payload.get(key)
        if isinstance(number, bool) or not isinstance(number, (int, float)):
            return None
        return number if not isinstance(number, float) or math.isfinite(number) else None
    return {
        "currencies": {"Units": value("Units"), "Nanites": value("Nanites"), "Quicksilver": value("Specials")},
        "base_count": _count(payload, "bases"),
        "inventory_count": _count(payload, "inventory"),
        "play_time": _play_time(payload.get("TotalPlayTime")),
        "observed_at": str(snapshot.get("observed_at") or ""),
        "partial": True,
        "warning": bool(payload.get("warning")),
    }


def save_report(text, snapshot, ui_locale="en", *, force=False):
    """Return None for ordinary chat, otherwise a fully deterministic report."""
    if not force and not is_report_request(text):
        return None
    locale = report_locale(text, ui_locale)
    if not snapshot:
        return ("Ainda não há um save lido para este personagem. Vincule ou importe um save em Expedição & diário. "
                "Não tenho números verificados para informar." if locale == "pt" else
                "No save has been read for this character yet. Link or import one in Expedition & journal. "
                "I have no verified save numbers to report.")
    payload = snapshot.get("payload") or {}
    labels = (("Unidades", payload.get("Units")), ("Nanites", payload.get("Nanites")),
              ("Quicksilver", payload.get("Specials")), ("Bases", _count(payload, "bases")),
              ("Entradas legíveis de inventário", _count(payload, "inventory"))) if locale == "pt" else (
              ("Units", payload.get("Units")), ("Nanites", payload.get("Nanites")),
              ("Quicksilver", payload.get("Specials")), ("Base count", _count(payload, "bases")),
              ("Readable inventory entries", _count(payload, "inventory")))
    lines = ["Dados do save — lidos diretamente pelo aplicativo." if locale == "pt" else
             "Saved facts — read directly by the app."]
    lines.extend(f"- {label}: {_number(value, locale)}" for label, value in labels)
    played = _play_time(payload.get("TotalPlayTime"))
    if played is not None:
        lines.append(("Tempo de jogo salvo" if locale == "pt" else "Saved play time") + f": {played}")
    stamp = str(snapshot.get("observed_at") or "")
    if stamp:
        lines.append(("Data do snapshot: " if locale == "pt" else "Snapshot timestamp: ") + stamp)
    lines.append("O inventário pode estar incompleto; os totais acima contam apenas entradas reconhecidas. Não é uma leitura ao vivo." if locale == "pt" else
                 "Inventory may be incomplete; its count includes recognized entries only. This is a historical snapshot, not a live reading.")
    if payload.get("warning"):
        lines.append("O leitor registrou um aviso; confira os detalhes do snapshot." if locale == "pt" else
                     "The reader reported a warning; check the snapshot details.")
    if re.search(r"\b(ideas?|suggest|suggestions?|activities|activity|next|should|ideias?|sugira|sugestoes|atividades|proximos?|deveriamos)\b", _plain(text)):
        lines += ["", "Ideias de atividades — sugestões do aplicativo, não missões salvas:" if locale == "pt" else
                  "Activity ideas — app suggestions, not saved missions:"]
        named = next((str(row.get("Name", "")).strip() for row in payload.get("bases", [])
                      if isinstance(row, dict) and row.get("Name")), "")
        named = " ".join(named.split())[:180]
        first = (f'Revisite "{named}" e registre o que existe lá; o nome não confirma instalações ou produção.' if named else
                 "Escolha um destino de exploração e registre o que encontrar no diário.") if locale == "pt" else (
                 f'Revisit "{named}" and record what is there; its name does not confirm facilities or production.' if named else
                 "Choose an exploration destination and record what you find in the journal.")
        suggestions = [first,
                       "Revise um inventário e defina uma meta de recursos com base no que você confirmar no jogo." if locale == "pt" else
                       "Review an inventory container and set a resource goal based on what you confirm in the game.",
                       "Registre seu próximo objetivo no diário de Ori para retomar a viagem depois." if locale == "pt" else
                       "Record your next objective in Ori's journal so you can resume it later."]
        lines.extend(f"{index}. {idea}" for index, idea in enumerate(suggestions, 1))
    lines.append("\nEste relatório foi montado pelo aplicativo, sem geração de números por IA." if locale == "pt" else
                 "\nThis report was formatted by the app, without AI-generated numbers.")
    return "\n".join(lines)


def report_chunks(report):
    # The normal stream loop can check cancellation between complete lines.
    yield from report.splitlines(keepends=True)
